// Three questions, one answer. The first two are about workflows that stopped;
// the third is about a workflow that runs, reports success, and does nothing —
// which neither an error handler nor a liveness check can see, and which is
// exactly what happened on 2026-08-13: chathistory-sync wrote every message
// with no course for hours, in green executions.
const WATCHED = [
  { id: 'smartrag-chathistory-sync',  label: 'ChatHistory Sync',      maxHours: 1 },
  { id: 'smartrag-usermemory-summary', label: 'UserMemory Summary',   maxHours: 9 },
  { id: 'smartrag-ingest-document',   label: 'Document Ingest',       maxHours: null },
  { id: 'smartrag-langfuse-userid-patch', label: 'Langfuse userId patch', maxHours: 2 },
];

const problems = [];

// ── 1. every watched workflow still exists and is active ────────────────────
const rows = $('Last success per workflow').all().map(i => i.json);
const byId = Object.fromEntries(rows.map(r => [String(r.id), r]));

for (const w of WATCHED) {
  const row = byId[w.id];
  if (!row) {
    problems.push(`${w.label}: not present in n8n (id ${w.id}). Deploy the workflows.`);
    continue;
  }
  if (row.active === false) {
    problems.push(`${w.label}: deactivated. It will never run again until it is switched on.`);
    continue;
  }
  // ── 2. …and produced a success recently enough ────────────────────────────
  // A workflow with no schedule (the ingest runs on a webhook) has no
  // expected interval, so silence is not a fault and maxHours is null.
  if (w.maxHours === null) continue;
  if (!row.last_success) {
    problems.push(`${w.label}: has never completed successfully.`);
    continue;
  }
  const hours = (Date.now() - new Date(row.last_success).getTime()) / 3600000;
  if (hours > w.maxHours) {
    problems.push(
      `${w.label}: last success ${hours.toFixed(1)} h ago, expected within ` +
      `${w.maxHours} h (${new Date(row.last_success).toISOString()}).`);
  }
}

// ── 3. green, and nothing happened ──────────────────────────────────────────
// Messages that have been in Flowise for longer than the sync's interval plus
// a margin must be in Weaviate. If they are not, the sync is running and
// failing to do its job — the failure shape that has no error.
const settled = Number(($('Settled messages').first().json || {}).n || 0);
if (settled > 0) {
  const url = `http://smartrag-weaviate:${$env.WEAVIATE_HTTP_PORT || 8080}/v1/graphql`;
  const res = await this.helpers.httpRequest({
    method: 'POST', url,
    headers: { 'Authorization': `Bearer ${$env.WEAVIATE_API_KEY}`,
               'Content-Type': 'application/json' },
    body: { query: '{ Aggregate { ChatHistory { meta { count } } } }' },
    json: true, returnFullResponse: true, ignoreHttpStatusErrors: true,
  });
  const body = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
  const stored = body?.data?.Aggregate?.ChatHistory?.[0]?.meta?.count;
  if (res.statusCode >= 400 || stored === undefined) {
    problems.push(`Weaviate did not answer the ChatHistory count (HTTP ${res.statusCode}).`);
  } else if (stored < settled) {
    // Less than, not "not equal": Weaviate also holds messages whose Flowise
    // rows were deleted, so more stored than sent is normal and only fewer is
    // a symptom.
    problems.push(
      `${settled - stored} chat message(s) have been in Flowise for over 15 ` +
      `minutes and are not in Weaviate (${stored} stored, ${settled} sent). ` +
      `The sync may be running and writing nothing.`);
  }
}

if (problems.length === 0) return [];
return [{ json: { count: problems.length, report: problems.join('\n'),
                  when: new Date().toISOString() } }];

// ─── the shared alert state ──────────────────────────────────────────────────
// A mail per failure is a mail every five minutes for a workflow that runs
// every five minutes: 288 a day, and after the second day nobody reads any of
// them — including the one that matters. So a subject that is already known
// to be broken stays quiet for a while, and the next mail says how many
// failures it stands for.
//
// The state lives in Weaviate's WorkflowState under a fixed id, the same way
// chathistory-sync keeps its cursor. The status is read from the response
// rather than from a thrown error: a Code node runs in the task runner, and
// an exception loses its structured fields crossing that boundary, so a 404
// on the first run would arrive as an unexplained failure.
const QUIET_MINUTES = Number($env.ALERT_QUIET_MINUTES || 60);
const STATE_ID = 'a1e6d9c4-2f38-4b07-9c15-6de0f4a81b23';
const base = `http://smartrag-weaviate:${$env.WEAVIATE_HTTP_PORT || 8080}`;
const headers = {
  'Authorization': `Bearer ${$env.WEAVIATE_API_KEY}`,
  'Content-Type': 'application/json'
};

async function readState() {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `${base}/v1/objects/WorkflowState/${STATE_ID}`,
    headers,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  if (res.statusCode === 404) return {};          // first run
  if (res.statusCode >= 400) {
    // Not fatal: an alert that cannot read its throttle should still be sent.
    console.log(`Alert state unreadable (HTTP ${res.statusCode}) — not throttling.`);
    return {};
  }
  const body = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
  try {
    return JSON.parse(body?.properties?.value || '{}');
  } catch (e) {
    return {};
  }
}

async function writeState(state) {
  const payload = { properties: { key: 'alertState', value: JSON.stringify(state) } };
  const patched = await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${base}/v1/objects/WorkflowState/${STATE_ID}`,
    headers, body: payload,
    returnFullResponse: true, ignoreHttpStatusErrors: true,
  });
  if (patched.statusCode !== 404) return;
  // PATCH on something that does not exist is a 404, so the first run has to
  // create it — without this the state could never be written even once.
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${base}/v1/objects`,
    headers,
    body: { class: 'WorkflowState', id: STATE_ID, ...payload },
    returnFullResponse: true, ignoreHttpStatusErrors: true,
  });
}

const item = $input.first().json;
const state = await readState.call(this);
const now = Date.now();
const entry = state['watchdog'] || { last: 0, suppressed: 0 };
const minutesSince = (now - Number(entry.last || 0)) / 60000;

// An unattended problem is reported once and then hourly silence, not an
// hourly mail — the vhb installation sent one every hour for a placeholder id
// that had never been filled in, which is how its watchdog stopped being read.
if (minutesSince < QUIET_MINUTES) {
  entry.suppressed = Number(entry.suppressed || 0) + 1;
  state['watchdog'] = entry;
  await writeState.call(this, state);
  console.log(`Suppressed: watchdog reported ${minutesSince.toFixed(0)} minute(s) ago.`);
  return [];
}

const quietChecks = Number(entry.suppressed || 0);
state['watchdog'] = { last: now, suppressed: 0 };
await writeState.call(this, state);
return [{ json: { ...item, quietChecks, quietMinutes: QUIET_MINUTES } }];

